package kpt.core.model.config

/**
 * Security defaults a fresh install starts with.
 *
 * **SoT: `app-profile/app.yaml#security`.** The block below is GENERATED by `./gradlew syncForkConfig`;
 * change the YAML, not this file. A fork keeps capture blocked (the default) or allows it without
 * touching template code.
 *
 * These are STARTING values only. `UserData.DEFAULT` reads them for a first run; once the user makes a
 * choice (Settings → "Allow screen capture"), `core/datastore` persists it and that choice wins.
 */
object AppSecurityConfig {
    // syncForkConfig:app-security:begin — GENERATED from app-profile/app.yaml#security. Do not hand-edit.
    /** `security.screen_capture_allowed_by_default` — whether a fresh install allows screenshots + recording. */
    const val SCREEN_CAPTURE_ALLOWED_BY_DEFAULT: Boolean = false

    /** `security.signed_in_by_default` — whether a fresh install starts signed in (false = the app has a login). */
    const val SIGNED_IN_BY_DEFAULT: Boolean = true

    /** `security.first_run_onboarding` — whether a fresh install shows onboarding once (false = skip it). */
    const val FIRST_RUN_ONBOARDING: Boolean = false
    // syncForkConfig:app-security:end
}
